def string_length(s):
    return len(s)

if __name__ == '__main__':
    s = input()
    print(string_length(s))

def max(lst):
    max_val = lst[0]
    for val in lst:
        if val > max_val:
            max_val = val
    return max_val

print(max([1, 2, 3, 4, 5]))
